// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        // owner is the test contract (deployer). Contract starts with zero balance.
        // Any positive amount exceeds the contract's balance.
        amount = bound(amount, 1, type(uint256).max);
        vm.assume(amount > address(c).balance);
        bool ok;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }
        // Reference: transfer of an over-balance amount reverts => ok == false.
        // Mutant: transfer removed, withdraw silently succeeds => ok == true.
        assertTrue(!ok, "withdraw of more than the balance must revert");
    }
}
